import{_ as a,o as h,c as t,a3 as i}from"./chunks/framework.DX_KL3e0.js";const p=JSON.parse('{"title":"Ngày đầu đi làm","description":"","frontmatter":{},"headers":[],"relativePath":"bat-dau/ngay-dau-di-lam.md","filePath":"bat-dau/ngay-dau-di-lam.md","lastUpdated":1782143716000}'),e={name:"bat-dau/ngay-dau-di-lam.md"};function o(c,n,l,r,g,m){return h(),t("div",null,[...n[0]||(n[0]=[i('<h1 id="ngay-đau-đi-lam" tabindex="-1">Ngày đầu đi làm <a class="header-anchor" href="#ngay-đau-đi-lam" aria-label="Permalink to &quot;Ngày đầu đi làm&quot;">​</a></h1><p>Chào mừng bạn gia nhập! Trang này là <strong>danh sách việc cần làm trong ngày đầu</strong> để bạn bắt đầu thật nhanh với FADO AssetFlow. Làm lần lượt từ trên xuống là đủ.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Dành cho:</strong> nhân viên mới (mọi vai trò).</li><li><strong>Thời gian:</strong> ~10–15 phút.</li><li><strong>Cần có:</strong> tài khoản đăng nhập (do Quản trị/HCNS cấp). Chấm công chủ yếu bằng <strong>máy vân tay</strong>; chấm công bằng điện thoại chỉ áp dụng cho một số bộ phận đặc thù.</li></ul></div><h2 id="✅-viec-can-lam" tabindex="-1">✅ Việc cần làm <a class="header-anchor" href="#✅-viec-can-lam" aria-label="Permalink to &quot;✅ Việc cần làm&quot;">​</a></h2><h3 id="_1-đang-nhap-đoi-mat-khau" tabindex="-1">1. Đăng nhập &amp; đổi mật khẩu <a class="header-anchor" href="#_1-đang-nhap-đoi-mat-khau" aria-label="Permalink to &quot;1. Đăng nhập &amp; đổi mật khẩu&quot;">​</a></h3><ul><li>[ ] Đăng nhập bằng email và mật khẩu được cấp → <a href="/help/bat-dau/dang-nhap.html">Đăng nhập &amp; đăng xuất</a></li><li>[ ] Đổi sang mật khẩu riêng của bạn → <a href="/help/quan-tri/cai-dat.html">Cài đặt hệ thống</a></li></ul><h3 id="_2-lam-quen-giao-dien" tabindex="-1">2. Làm quen giao diện <a class="header-anchor" href="#_2-lam-quen-giao-dien" aria-label="Permalink to &quot;2. Làm quen giao diện&quot;">​</a></h3><ul><li>[ ] Xem qua <strong>Sidebar</strong> (điều hướng), <strong>Topbar</strong> (tìm kiếm, thông báo, trợ giúp) → <a href="/help/bat-dau/giao-dien-chung.html">Giao diện chung</a></li><li>[ ] Bấm nút <strong>?</strong> trên thanh trên cùng bất cứ lúc nào để mở đúng trang hướng dẫn của màn hình đang xem.</li></ul><h3 id="_3-hoan-thien-ho-so-ca-nhan" tabindex="-1">3. Hoàn thiện hồ sơ cá nhân <a class="header-anchor" href="#_3-hoan-thien-ho-so-ca-nhan" aria-label="Permalink to &quot;3. Hoàn thiện hồ sơ cá nhân&quot;">​</a></h3><ul><li>[ ] Cập nhật thông tin cá nhân, ảnh đại diện, liên hệ khẩn cấp → <a href="/help/chuc-nang/ho-so-cua-toi.html">Hồ sơ của tôi</a></li><li>[ ] Kiểm tra hợp đồng và thông tin nhân sự của bạn.</li></ul><h3 id="_4-kiem-tra-du-lieu-cham-cong" tabindex="-1">4. Kiểm tra dữ liệu chấm công <a class="header-anchor" href="#_4-kiem-tra-du-lieu-cham-cong" aria-label="Permalink to &quot;4. Kiểm tra dữ liệu chấm công&quot;">​</a></h3><ul><li>[ ] Hầu hết nhân viên chấm công bằng <strong>máy vân tay</strong>. Hãy chấm thử rồi kiểm tra dữ liệu đã về <strong>đúng tên bạn</strong> → <a href="/help/chuc-nang/cham-cong.html">Chấm công &amp; Nghỉ phép</a></li><li>[ ] Nếu chưa thấy dữ liệu hoặc hiện sai người, báo HCNS để <strong>gán mã chấm công</strong> cho bạn.</li><li>[ ] <em>(Chỉ một số bộ phận đặc thù)</em> Chấm công bằng <strong>điện thoại</strong>: cho phép trình duyệt truy cập <strong>camera</strong> + <strong>vị trí (GPS)</strong> rồi điểm danh.</li><li>[ ] (Tùy chọn) Khai báo <strong>Telegram Chat ID</strong> trong hồ sơ cá nhân để nhận thông báo qua Telegram</li></ul><h3 id="_5-biet-noi-can-đen-khi-can" tabindex="-1">5. Biết nơi cần đến khi cần <a class="header-anchor" href="#_5-biet-noi-can-đen-khi-can" aria-label="Permalink to &quot;5. Biết nơi cần đến khi cần&quot;">​</a></h3><ul><li>[ ] Gửi yêu cầu hỗ trợ (CNTT, hành chính...) → <a href="/help/chuc-nang/tickets.html">Ticket Hỗ trợ</a></li><li>[ ] Đặt phòng họp → <a href="/help/chuc-nang/dat-phong.html">Đặt phòng họp</a></li><li>[ ] Xem tài sản được cấp cho bạn → <a href="/help/chuc-nang/tra-cuu.html">Tra cứu</a></li><li>[ ] Xin nghỉ phép, xem quỹ phép năm → <a href="/help/chuc-nang/cham-cong.html">Chấm công &amp; Nghỉ phép</a></li></ul><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Tôi không đăng nhập được?</strong> Kiểm tra lại email/mật khẩu. Nếu quên mật khẩu, dùng chức năng đặt lại qua email hoặc liên hệ Quản trị/HCNS. Xem <a href="/help/bat-dau/dang-nhap.html">Đăng nhập &amp; đăng xuất</a>.</p><p><strong>Tôi không thấy một số menu?</strong> Menu hiển thị theo vai trò và phân quyền. Nếu thiếu mục bạn cần dùng cho công việc, hãy đề nghị Admin cấp quyền. Xem <a href="/help/bat-dau/phan-quyen.html">Phân quyền &amp; vai trò</a>.</p><p><strong>Chấm vân tay rồi nhưng không thấy dữ liệu của tôi?</strong> Thường do <strong>mã chấm công chưa được gán</strong> cho bạn. Liên hệ HCNS để gán mã; sau đó dữ liệu sẽ hiển thị đúng tên. Xem <a href="/help/chuc-nang/cham-cong.html">Chấm công &amp; Nghỉ phép</a>.</p><p><strong>Chấm công bằng điện thoại báo lỗi thiếu GPS/ảnh?</strong> <em>(bộ phận đặc thù)</em> Cần có cả ảnh selfie và GPS, dùng kết nối HTTPS. Trên iPhone/Safari hãy mở quyền vị trí trong Cài đặt.</p><h2 id="buoc-tiep-theo" tabindex="-1">Bước tiếp theo <a class="header-anchor" href="#buoc-tiep-theo" aria-label="Permalink to &quot;Bước tiếp theo&quot;">​</a></h2><p>Đọc trang hướng dẫn dành riêng cho vai trò của bạn: <a href="/help/vai-tro/nguoi-dung-cuoi.html">Người dùng cuối</a> · <a href="/help/vai-tro/quan-ly.html">Quản lý</a> · <a href="/help/vai-tro/admin.html">Admin</a> · <a href="/help/vai-tro/super-admin.html">Super Admin</a></p><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/gioi-thieu.html">Giới thiệu hệ thống</a> · <a href="/help/bat-dau/giao-dien-chung.html">Giao diện chung</a> · <a href="/help/chuc-nang/ho-so-cua-toi.html">Hồ sơ của tôi</a></p>',23)])])}const s=a(e,[["render",o]]);export{p as __pageData,s as default};
